#!/usr/bin/env python3 # -*- coding: utf-8 -*- """ CF Subscription Health Check (runs on GitHub Actions) Checks:   1. Subscription OK: HTTP 200, nodes >= 8, all direct (no CF random IPs)   2. Admin /login returns full HTML   3. Root path returns nginx fake page Auto-fix:   - POST Vercel Deploy Hook to trigger production deployment (no API token)   - Poll subscription until recovered """ import urllib.request import json import re import os import sys import time import gzip  SUB_URL = os.environ.get('SUB_URL', '') DEPLOY_HOOK_URL = os.environ.get('DEPLOY_HOOK_URL', '') BASE = 'https://www.xiow123.duckdns.org'  # 35 个真实可用节点白名单（34 个 Vercel 优选 IP + 主域名，全 443） # 与 _worker_node.js 默认直连地址保持一致；健康检查按 server 校验，任何白名单外节点视为异常 ALLOWED_SERVERS = {     'www.xiow123.duckdns.org',     'edgetunnel-vercel-orcin.vercel.app',  # 备用域名（可能休眠，保留以便恢复）     '76.76.21.98', '76.76.21.142', '76.76.21.113', '76.76.21.111', '76.76.21.200',     '76.76.21.101', '76.76.21.202', '76.76.21.102', '76.76.21.203', '76.76.21.241',     '76.76.21.103', '76.76.21.22', '76.76.21.104', '76.76.21.123', '76.76.21.164',     '76.76.21.110', '76.76.21.9', '76.76.21.93', '76.76.21.116', '76.76.21.201',     '76.76.21.21', '76.76.21.109', '76.76.21.107', '76.76.21.115', '76.76.21.100',     '76.76.21.61', '76.76.21.114', '76.76.21.106', '76.76.21.117', '76.76.21.105',     '76.76.21.112', '76.76.21.75', '76.76.21.108', }   def fetch(url, ua='Mozilla/5.0', timeout=40):     req = urllib.request.Request(url, headers={'User-Agent': ua, 'Accept-Encoding': 'gzip'})     resp = urllib.request.urlopen(req, timeout=timeout)     data = resp.read()     if data[:2] == b'\x1f\x8b':         data = gzip.decompress(data)     return resp.status, data   def parse_nodes(text):     """Parse (name, server) list from Clash YAML"""     nodes = []     if 'proxies:' in text:         proxies_section = text.split('proxies:')[1] if 'proxies:' in text else text         # single-line: {name: X, server: Y, port: N, type: vless, ...}         for m in re.finditer(r'\{name:\s*([^,]+),\s*server:\s*([^,\s}]+)', proxies_section):             nodes.append((m.group(1).strip(), m.group(2).strip()))         if not nodes:             # multi-line format             names = re.findall(r'name:\s*([^,]+),', proxies_section)             servers = re.findall(r'server:\s*([^,\s}]+)', proxies_section)             for n, s in zip(names, servers):                 nodes.append((n.strip(), s.strip()))     else:         # plain vless:// text         for line in text.split('\n'):             line = line.strip()             if line.startswith('vless://'):                 m = re.search(r'@([^:]+):(\d+)', line)                 if m:                     nodes.append((line[:30], m.group(1)))     # filter DNS config noise     return [(n, s) for n, s in nodes if s and '.' in s and not s.startswith('-')]   def trigger_deploy_hook():     """POST Vercel Deploy Hook to trigger production deployment"""     if not DEPLOY_HOOK_URL:         print('  DEPLOY_HOOK_URL not configured')         return False     try:         req = urllib.request.Request(DEPLOY_HOOK_URL, method='POST')         resp = urllib.request.urlopen(req, timeout=40)         body = resp.read().decode('utf-8', errors='ignore')         print('  Deploy Hook HTTP %s: %s' % (resp.status, body[:200]))         return 200 <= resp.status < 300     except Exception as e:         print('  Deploy Hook trigger failed: %s' % e)         return False   def wait_sub_ok(timeout=360):     """Poll subscription until recovered (deploy finished)"""     t0 = time.time()     while time.time() - t0 < timeout:         try:             status, data = fetch(SUB_URL, 'clash-verge/2.0.0')             text = data.decode('utf-8', errors='ignore')             nodes = parse_nodes(text)             servers = [s for _, s in nodes]             bad = [s for s in servers if s not in ALLOWED_SERVERS]             ok = status == 200 and len(nodes) >= 8 and len(bad) == 0             print('  poll: HTTP %s, nodes=%d, bad=%d' % (status, len(nodes), len(bad)))             if ok:                 return True         except Exception as e:             print('  poll fetch failed: %s' % e)         time.sleep(30)     return False   def main():     results = []     all_ok = True      # 1. subscription check     print('[1] subscription check')     try:         status, data = fetch(SUB_URL, 'clash-verge/2.0.0')         text = data.decode('utf-8', errors='ignore')         nodes = parse_nodes(text)         servers = [s for _, s in nodes]         n = len(nodes)         bad = [s for s in servers if s not in ALLOWED_SERVERS]         ok = status == 200 and n >= 8 and len(bad) == 0         print('  HTTP %s, nodes=%d, bad=%d' % (status, n, len(bad)))         if bad:             print('  bad servers:', bad[:3])         results.append(('sub ok (>=8 direct)', ok))         all_ok = all_ok and ok     except Exception as e:         print('  sub fetch failed: %s' % e)         results.append(('sub ok (>=8 direct)', False))         all_ok = False      # 2. admin login page     print('[2] admin /login check')     try:         status, data = fetch(BASE + '/login')         text = data.decode('utf-8', errors='ignore')         ok = status == 200 and ('<!DOCTYPE html>' in text[:80] or '设置页面' in text)         print('  HTTP %s, %d bytes, HTML=%s' % (status, len(data), ok))         results.append(('admin login HTML', ok))         all_ok = all_ok and ok     except Exception as e:         print('  admin check failed: %s' % e)         results.append(('admin login HTML', False))         all_ok = False      # 3. root fake page     print('[3] root fake page check')     try:         status, data = fetch(BASE + '/')         ok = status == 200 and b'Welcome to nginx' in data         print('  HTTP %s, %d bytes, nginx=%s' % (status, len(data), ok))         results.append(('root nginx fake', ok))         all_ok = all_ok and ok     except Exception as e:         print('  root check failed: %s' % e)         results.append(('root nginx fake', False))         all_ok = False      print()     for name, ok in results:         print('  %s %s' % ('PASS' if ok else 'FAIL', name))      if all_ok:         print('\nOK: all health checks passed')         return 0      # auto-fix: POST Deploy Hook to redeploy     print('\nWARN: issues found, POST Deploy Hook to redeploy...')     if not trigger_deploy_hook():         print('FAIL: Deploy Hook trigger failed')         return 1     print('deploy triggered, waiting for subscription to recover (max 6 min)...')     if wait_sub_ok():         print('OK: auto-fix success, subscription recovered')         return 0     else:         print('FAIL: subscription recovery timeout, manual action needed')         return 1   if __name__ == '__main__':     sys.exit(main())
